from collections import deque

def shortest_subarray_ge_target(nums: list[int], target: int) -> int:
    n = len(nums)
    prefix = [0] * (n + 1)
    for i, x in enumerate(nums):
        prefix[i + 1] = prefix[i] + x
    best = n + 1
    q = deque()
    for i, p_val in enumerate(prefix):
        while q and p_val - prefix[q[0]] >= target:
            best = min(best, i - q.popleft())
        while q and prefix[q[-1]] >= p_val:
            q.pop()
        q.append(i)
    return 0 if best > n else best

def shortest_subarray_ge_target(nums: list[int], target: int) -> int:
    n = len(nums)
    best = n + 1
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += nums[j]
            if s >= target:
                best = min(best, j - i + 1)
                break
    return 0 if best > n else best

def first_at_least(nums: list[int], target: int) -> int:
    left, right = 0, len(nums) - 1
    ans = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] >= target:
            ans = mid
            right = mid - 1
        else:
            left = mid + 1
    return ans

def first_at_least(nums: list[int], target: int) -> int:
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] >= target:
            hi = mid
        else:
            lo = mid + 1
    return lo if lo < len(nums) else -1

def max_product_subarray(nums: list[int]) -> int:
    hi = lo = ans = nums[0]
    for x in nums[1:]:
        hi, lo = max(x, hi * x, lo * x), min(x, hi * x, lo * x)
        ans = max(ans, hi)
    return ans
